/*
Day #24/24: Spider Graph
https://openprocessing.org/sketch/2410114
https://mathober.com/
https://openprocessing.org/curation/87980
*/

let S, N, FCD, datasets;

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(2, 2, 8);
	describe("random datasets in spider graph with random amount of variables with color cyan to purple on dark background");
	frameRate(60);

  noFill();
	S = max(width, height);
	N = ~~random(3, 11);
	FCD = ~~random(100, 500);

	datasets = [];
	addDataset(N);
  loop();
}

function addDataset(num) {
	let pts = [];
	for (let i = 0; i < num; i++) {
		pts[i] = random();
	}
	const clr = lerpColor(color("cyan"), color("purple"), random());
	const lt = random(0.75, 2);
	datasets.push({pts, clr, lt});
}

function draw() {
	if (frameCount%30 === 0) addDataset(N);
	datasets = datasets.filter((d) => d.lt > 0);
	background(2, 2, 8);
	translate(width/2, height/2)
	rotate(noisom(1, 1.4, FCD)-1.2); // to avoid symmetries in nosir, instaed of (-0.2, 0.2)

	strokeWeight(1);
	drawPts();

	strokeWeight(3);
	for (let d of datasets) drawPts(d);
}

function drawPts(d = null) {
	const r = max(width, height) * 0.45;
	const da = TWO_PI / N;
	if (d) {
		noFill();
		var clr = d.clr;
		clr.setAlpha(d.lt*255)
		d.lt -= 0.01;
		stroke(clr);
		beginShape();
	} else {
		stroke("silver")
	}
	for (let a = 0, i = 0; a < TWO_PI; a+=da, i++) {
		const f = d ? d.pts[i] : 1;
		const x = cos(a) * r * f;
		const y = sin(a) * r * f;
		if (d) {
			vertex(x, y)
			circle(x, y, 10);
		} else {
			line(0, 0, x, y);
		}
	}
	if (d) endShape(CLOSE);
}


function noisom(v1, v2, fcd = 234) {
	if (v1>v2) [v1, v2] = [v2, v1];
	const n = noise(v1, v2, frameCount/234);
	return v1+n*(v2-v1);
}

function mouseClicked() {
  if (mouseButton === LEFT) setup();
}
